// ============================================================
// FSMGuard Patch - Transition Pruning
// CWE: CWE-1233
// Parameter: safe_redirect
// Strictness: strict
// ============================================================
// This patch removes or redirects unsafe transition to EXPLOIT
// Added by FSMGuard Stage 08 based on RL agent decision



// Transition SAFELY REDIRECTED by FSMGuard with alert
// CWE CWE-1233 mitigation - monitored redirect
always @(posedge clk) begin
    if (next_state_logic == EXPLOIT) begin
        // Unsafe transition detected - alert and redirect
        alert_signal = 1'b1;
        next_state = SAFE_STATE;
    end
end



// ============================================================
// End FSMGuard Patch
// ============================================================
